// Focused isolated research controls. Mathematical constants are independent
// known words/identities, not values generated by the candidate or host libm.
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
import test from 'node:test';
import * as K from './kernel.mjs';
import * as W from './words.mjs';
import { C } from './constants.mjs';
import { currentPolicy } from './wrappers.mjs';
import { run } from './run.mjs';
const value = W.fromBits;
const bits = W.toBits;

test('all eight original source identities and notices, exact constant words', () => {
  const manifest = JSON.parse(readFileSync(new URL('./sources.json', import.meta.url)));
  assert.equal(manifest.files.length, 8);
  for (const entry of manifest.files) {
    const raw = readFileSync(new URL(`./upstream/${entry.file}`, import.meta.url));
    assert.equal(raw.length, entry.bytes, entry.file);
    assert.equal(createHash('sha256').update(raw).digest('hex'), entry.sha256, entry.file);
    assert.match(raw.toString(), /Sun Microsystems/);
  }
  const frozen = JSON.parse(readFileSync(new URL('./constants.json', import.meta.url)));
  for (const [literal, word] of Object.entries(frozen.literals)) assert.equal(bits(C[literal]), word);
  assert.equal(bits(C['0.33333333333333333']), '3fd5555555555555');
  assert.equal(bits(C['8.0085662595372944372e-0017']), '3c971547652b82fe');
  assert.equal(bits(C['1.0e-300']), '01a56e1fc2f8f359');
  const kernel = readFileSync(new URL('./kernel.mjs', import.meta.url), 'utf8');
  assert.doesNotMatch(kernel, /Math\.(?:pow|log|exp|sqrt|fround)|\*\*/);
  assert.doesNotMatch(kernel, /wrappers|fractional_kernel_required|currentPolicy/);
});

test('whole-word access, shifts, wrap, carry/borrow and exception bit transforms', () => {
  for (const word of ['0000000000000000', '8000000000000000', '0000000000000001',
    '0010000000000000', '7fefffffffffffff', '7ff0000000000000', 'fff0000000000000']) {
    const x = value(word);
    assert.equal(bits(W.fromWords(W.hi(x), W.lo(x))), word);
    assert.equal(bits(W.withHi(x, W.hi(x))), word);
    assert.equal(bits(W.withLo(x, W.lo(x))), word);
  }
  assert.equal(W.shl(-1, 0), -1); assert.equal(W.shl(-1, 32), 0);
  assert.equal(W.shr(-1, 0), 0xffffffff); assert.equal(W.shr(-1, 32), 0);
  assert.equal(W.sar(-1, 32), -1); assert.equal(W.sar(0x7fffffff, 32), 0);
  assert.equal(W.add32(0x7fffffff, 1), -2147483648);
  assert.equal(W.uadd32(0xffffffff, 1), 0);
  assert.equal(W.usub32(0, 1), 0xffffffff);
  for (const n of [-1, 33, 1.5]) assert.throws(() => W.shr(1, n), RangeError);
  assert.equal(bits(K.fabs(-0)), '0000000000000000');
  assert.equal(bits(K.copysign(0, -1)), '8000000000000000');
  assert.equal(bits(K.copysign(Infinity, -1)), 'fff0000000000000');
});

test('software sqrt and scalbn exact known answers including count32 subnormals', () => {
  const roots = [
    ['0000000000000001', '1e60000000000000'],
    ['0010000000000000', '2000000000000000'],
    ['4000000000000000', '3ff6a09e667f3bcd'],
    ['4010000000000000', '4000000000000000'],
    ['7fefffffffffffff', '5fefffffffffffff'],
    ['8000000000000000', '8000000000000000'],
    ['0000000000000000', '0000000000000000'],
  ];
  for (const [x, answer] of roots) assert.equal(bits(K.sqrt(value(x))), answer, x);
  assert(Number.isNaN(K.sqrt(-1))); assert.equal(K.sqrt(Infinity), Infinity);
  assert(Number.isNaN(K.sqrt(-Infinity)));
  for (const [x, n, answer] of [[1, -1074, '0000000000000001'], [1, -1075, '0000000000000000'],
    [3, -1075, '0000000000000002'], [-3, -1075, '8000000000000002'],
    [-0, 2147483647, '8000000000000000'], [1, 2147483647, '7ff0000000000000'],
    [-1, -2147483648, '8000000000000000']]) assert.equal(bits(K.scalbn(x, n)), answer);
  for (const n of [2147483648, -2147483649, .5, NaN]) assert.throws(() => K.scalbn(1, n), RangeError);
});

test('complete raw power executes fractional/general and signed special paths', () => {
  for (const [x, y, answer] of [[2, .5, '3ff6a09e667f3bcd'], [16, .25, '4000000000000000'],
    [8, 1 / 3, '4000000000000000'], [-2, -3, 'bfc0000000000000'],
    [-0, 3, '8000000000000000'], [-0, 2, '0000000000000000'],
    [-0, -3, 'fff0000000000000'], [0, 0, '3ff0000000000000'],
    [NaN, 0, '3ff0000000000000'], [Infinity, 0, '3ff0000000000000']]) {
    assert.equal(bits(K.pow(x, y)), answer, `${x}/${y}`);
  }
  assert(Number.isNaN(K.pow(-2, .5)));
  assert(Number.isNaN(K.pow(-1, Infinity)));
  assert.equal(K.pow(-1, 9007199254740991), -1);
  assert.equal(K.pow(-1, 9007199254740992), 1);
  assert.equal(K.pow(.5, Number.MAX_VALUE), 0);
  assert.equal(K.pow(2, Number.MAX_VALUE), Infinity);
  assert.equal(bits(K.pow(value('601dd55745cbb7ed'), -2)), '000012688b70e62b');
});

test('raw log/exp exceptional classes and exact zero/unit/log2 controls', () => {
  assert.equal(bits(K.log(1)), '0000000000000000');
  assert.equal(bits(K.log(2)), '3fe62e42fefa39ef');
  assert.equal(bits(K.exp(0)), '3ff0000000000000');
  assert.equal(bits(K.exp(-0)), '3ff0000000000000');
  assert.equal(K.log(0), -Infinity); assert.equal(K.log(-0), -Infinity);
  assert(Number.isNaN(K.log(-1))); assert.equal(K.log(Infinity), Infinity);
  assert(Number.isNaN(K.log(-Infinity))); assert(Number.isNaN(K.log(NaN)));
  assert.equal(K.exp(Infinity), Infinity); assert.equal(K.exp(-Infinity), 0);
  assert.equal(K.exp(1000), Infinity); assert.equal(K.exp(-1000), 0);
  assert(Number.isNaN(K.exp(NaN)));
});

test('observed public wrapper policy stays separate from raw internal exceptions', () => {
  assert.deepEqual(currentPolicy('pow', [null, 2]), { status: 'returned', value: null });
  assert.equal(currentPolicy('pow', [null, 'bad']).reason, 'type');
  assert.equal(currentPolicy('pow', [2]).reason, 'arity');
  assert.equal(currentPolicy('sqrt', [-1]).reason, 'domain');
  assert.equal(currentPolicy('log', [0]).reason, 'domain');
  assert.deepEqual(currentPolicy('pow', [Infinity, 0]), { status: 'returned', value: 1 });
  assert.deepEqual(currentPolicy('exp', [-Infinity]), { status: 'returned', value: 0 });
  assert.equal(currentPolicy('exp', [Infinity]).reason, 'nonfinite_result');
  assert.equal(currentPolicy('pow', [NaN, 0]).value, 1);
  assert.equal(currentPolicy('pow', [-2, .5]).reason, 'nonfinite_result');
  assert.equal(currentPolicy('log', [Infinity]).value, Infinity);
  assert(Number.isNaN(currentPolicy('log', [NaN]).value));
  assert.equal(currentPolicy('sqrt', [Infinity]).value, Infinity);
  assert(Number.isNaN(currentPolicy('sqrt', [NaN]).value));
  const discount = K.pow(value('601dd55745cbb7ed'), 2);
  assert.equal(discount, Infinity); assert.equal(1 / discount, 0);
  assert.equal(currentPolicy('pow', [value('601dd55745cbb7ed'), 2]).reason, 'nonfinite_result');
  assert.equal(run({ op: 'pow', x: '4000000000000000', y: '3fe0000000000000' }).bits, '3ff6a09e667f3bcd');
});

test('negative-unit parity/domain across every finite exponent field uses full exact words', () => {
  for (let field = 0; field < 0x7ff; field += 1) {
    for (const tail of [0n, 0x80000001n, 0xfffffffffffffn]) {
      const significand = field === 0 ? tail : (1n << 52n) | tail;
      const shift = field === 0 ? -1074 : field - 1075;
      const divisor = shift < 0 ? 1n << BigInt(-shift) : 1n;
      const integral = shift >= 0 || significand % divisor === 0n;
      const odd = integral && (shift > 0 ? false : ((significand / divisor) & 1n) !== 0n);
      for (const sign of [0n, 1n << 63n]) {
        const word = (sign | BigInt(field) << 52n | tail).toString(16).padStart(16, '0');
        const observed = K.pow(-1, value(word));
        if (!integral) assert(Number.isNaN(observed), word);
        else assert.equal(observed, odd ? -1 : 1, word);
      }
    }
  }
});
